"""Runtime material registry backed by the program-local JSON database."""

from __future__ import annotations

from collections.abc import Iterable
import json
from pathlib import Path

from materials import Material, MaterialRegistry


DEFAULT_MATERIALS_DATA = Path(__file__).resolve().with_name("materials_data.json")
MATERIALS_DATA_SCHEMA_VERSION = 1


def load_materials_data(
    data_path: str | Path = DEFAULT_MATERIALS_DATA,
) -> MaterialRegistry:
    """Load the self-contained runtime database generated by the import tool."""
    path = Path(data_path).expanduser().resolve()
    if not path.is_file():
        raise FileNotFoundError(
            f"runtime material database not found: {path}; "
            "run read_materials_lib.py to generate it"
        )
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(f"invalid runtime material database {path}: {exc}") from exc
    if payload.get("schema_version") != MATERIALS_DATA_SCHEMA_VERSION:
        raise ValueError(
            f"unsupported material database schema in {path}; "
            "run read_materials_lib.py again"
        )
    entries = payload.get("materials")
    if not isinstance(entries, list) or not entries:
        raise ValueError(f"runtime material database contains no materials: {path}")
    try:
        return MaterialRegistry(
            Material(**entry["parameters"])
            for entry in entries
        )
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError(f"invalid material record in {path}: {exc}") from exc


def get_material_library(
    names: Iterable[str] | None = None,
    *,
    data_path: str | Path = DEFAULT_MATERIALS_DATA,
) -> MaterialRegistry:
    """Load program-local materials, optionally selecting names.

    Normal simulations access only ``materials_data.json``.  The maintained CSV
    and its linked source files are needed solely when regenerating that file.
    """
    catalogue = load_materials_data(data_path)
    if names is None:
        return catalogue
    requested = [str(name).casefold() for name in names]
    by_name = {material.name.casefold(): material for material in catalogue}
    missing = sorted(set(requested).difference(by_name))
    if missing:
        raise KeyError(f"Unknown materials in runtime library: {missing}")
    return MaterialRegistry(by_name[name] for name in requested)


def available_materials(
    *, data_path: str | Path = DEFAULT_MATERIALS_DATA
) -> tuple[str, ...]:
    """Return embedded material names in material-ID order."""
    return tuple(material.name for material in load_materials_data(data_path))


def add_custom_material(
    materials: MaterialRegistry,
    *,
    name: str,
    density_g_cm3: float,
    molar_mass_g_mol: float,
    sputter_yield: float,
    angular_distribution_power: float,
    sigmund_a: float,
    sigmund_alpha: float,
    sigmund_beta: float,
    atoms_per_formula: float = 1.0,
    material_id: int | None = None,
    sticking_coefficient: float = 0.8,
    sticking_power: float = 2.0,
) -> MaterialRegistry:
    """Add a material whose supplied physical parameters are voltage independent.

    The simulation voltage is deliberately not part of this interface.  The
    same Y0, n, a, alpha and beta values are used at every simulation voltage.
    """
    clean_name = str(name).strip()
    if not clean_name:
        raise ValueError("custom material name cannot be empty")
    assigned_id = materials.max_id + 1 if material_id is None else int(material_id)
    custom = Material(
        material_id=assigned_id,
        name=clean_name,
        density_g_cm3=density_g_cm3,
        molar_mass_g_mol=molar_mass_g_mol,
        atoms_per_formula=atoms_per_formula,
        normal_sputter_yield_constant=sputter_yield,
        emission_power_constant=angular_distribution_power,
        sigmund_a=sigmund_a,
        sigmund_alpha=sigmund_alpha,
        sigmund_beta=sigmund_beta,
        sticking_coefficient=sticking_coefficient,
        sticking_power=sticking_power,
    )
    return materials.with_material(custom)
